import math
import random
import re

MOD = 998244353
MAX_N = 5000
REFERENCE_MAX_N = 14

SMALL_CASES = (
    "()",
    "()()",
    "(())",
    "(())()",
    "()(())",
    "()()()",
    "((()))",
    "(()())",
    "(((())))",
    "()()()()",
    "(())(())",
    "(()(()))",
    "()(())()",
)

STRESS_BLOCKS = (
    "()()()()()",
    "(()())()()",
    "((()))(())",
    "((()())())",
)


def _balanced(s: str) -> bool:
    balance = 0
    for ch in s:
        if ch == "(":
            balance += 1
        elif ch == ")":
            balance -= 1
        else:
            return False
        if balance < 0:
            return False
    return balance == 0


def _format_input(s: str) -> str:
    return f"{len(s)}\n{s}\n"


def _reverse_complement(s: str) -> str:
    return "".join(")" if ch == "(" else "(" for ch in reversed(s))


def validate_input(inp: str) -> bool:
    tokens = inp.split()
    if len(tokens) != 2:
        return False

    length_token, s = tokens
    if re.fullmatch(r"\+?[0-9]+", length_token) is None:
        return False

    digits = length_token.lstrip("+").lstrip("0") or "0"
    if len(digits) > len(str(MAX_N)):
        return False
    length = int(digits)
    return 1 <= length <= MAX_N and len(s) == length and _balanced(s)


def _random_balanced(rng: random.Random, pairs: int) -> str:
    chars = []
    opened = 0
    closed = 0
    while closed < pairs:
        if opened < pairs and (opened == closed or rng.randrange(2) == 0):
            chars.append("(")
            opened += 1
        else:
            chars.append(")")
            closed += 1
    return "".join(chars)


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    inputs = [_format_input(s) for s in SMALL_CASES[:max(0, n)]]
    while len(inputs) < n:
        inputs.append(_format_input(_random_balanced(rng, rng.randint(1, 4))))
    return inputs


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)

    core = "()(()())"
    depth = (MAX_N - len(core)) // 2
    deep = "(" * depth + core + ")" * depth

    blocks = list(STRESS_BLOCKS)
    for _ in range(MAX_N // len(STRESS_BLOCKS[0]) - len(blocks)):
        blocks.append(rng.choice(STRESS_BLOCKS))
    rng.shuffle(blocks)
    wide = "".join(blocks)

    return [_format_input(deep), _format_input(wide)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    if not validate_input(inp):
        return [("POST-1", "Input violates the length or sequence constraints.")]

    token = out.strip()
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return [("POST-2", "Expected exactly one decimal integer.")]

    digits = token.lstrip("+-").lstrip("0") or "0"
    if len(digits) > len(str(MOD - 1)) or (token.startswith("-") and digits != "0"):
        return [("POST-2", "The answer lies outside the residue range.")]
    answer = int(digits)
    if answer >= MOD:
        return [("POST-2", "The answer lies outside the residue range.")]

    s = inp.split()[1]
    pairs = len(s) // 2
    catalan = math.comb(len(s), pairs) // (pairs + 1)
    violations = []
    if catalan < MOD and not 1 <= answer <= catalan:
        violations.append(("POST-4", f"The answer must be between 1 and {catalan}."))
    if s in ("()" * pairs, "(" * pairs + ")" * pairs) and answer != 1:
        violations.append(("POST-5", "This sequence has exactly one reachable string."))
    return violations


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    pairs = []
    for inp in gen_small(seed, n):
        s = inp.split()[1]
        transformed = _reverse_complement(s)
        if transformed == s:
            transformed = "(" + s + ")"
        pairs.append(("POST-6", "equal", inp, _format_input(transformed)))
    return pairs


def reference_small(inp: str) -> str | None:
    if not validate_input(inp):
        return None
    s = inp.split()[1]
    if len(s) > REFERENCE_MAX_N:
        return None

    seen = {s}
    pending = [s]
    while pending:
        current = pending.pop()
        for left in range(len(current)):
            for right in range(left + 2, len(current) + 1, 2):
                substring = current[left:right]
                if _balanced(substring):
                    result = (
                        current[:left]
                        + _reverse_complement(substring)
                        + current[right:]
                    )
                    if result not in seen:
                        seen.add(result)
                        pending.append(result)
    return f"{len(seen) % MOD}\n"
